/**
 * @suppress
 */
public object FfiConverterUInt: FfiConverter<UInt, Int> {
    override fun lift(value: Int): UInt {
        return value.toUInt()
    }

    override fun read(buf: ByteBuffer): UInt {
        return lift(buf.getInt())
    }

    override fun lower(value: UInt): Int {
        return value.toInt()
    }

    override fun allocationSize(value: UInt) = 4UL

    override fun write(value: UInt, buf: ByteBuffer) {
        buf.putInt(value.toInt())
    }
}

/**
 * @suppress
 */
public object FfiConverterULong: FfiConverter<ULong, Long> {
    override fun lift(value: Long): ULong {
        return value.toULong()
    }

    override fun read(buf: ByteBuffer): ULong {
        return lift(buf.getLong())
    }

    override fun lower(value: ULong): Long {
        return value.toLong()
    }

    override fun allocationSize(value: ULong) = 8UL

    override fun write(value: ULong, buf: ByteBuffer) {
        buf.putLong(value.toLong())
    }
}

/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}



/**
 * What this build and client support (returned by `Client::capabilities`,
 * ADR step 6).
 *
 * Limits belong to the client's runtime context.
 */
data class Capabilities (
    var `apiVersion`: kotlin.UInt
    , 
    var `networks`: List<Network>
    , 
    var `features`: List<Feature>
    , 
    var `limits`: Limits
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCapabilities: FfiConverterRustBuffer<Capabilities> {
    override fun read(buf: ByteBuffer): Capabilities {
        return Capabilities(
            FfiConverterUInt.read(buf),
            FfiConverterSequenceTypeNetwork.read(buf),
            FfiConverterSequenceTypeFeature.read(buf),
            FfiConverterTypeLimits.read(buf),
        )
    }

    override fun allocationSize(value: Capabilities) = (
            FfiConverterUInt.allocationSize(value.`apiVersion`) +
            FfiConverterSequenceTypeNetwork.allocationSize(value.`networks`) +
            FfiConverterSequenceTypeFeature.allocationSize(value.`features`) +
            FfiConverterTypeLimits.allocationSize(value.`limits`)
    )

    override fun write(value: Capabilities, buf: ByteBuffer) {
            FfiConverterUInt.write(value.`apiVersion`, buf)
            FfiConverterSequenceTypeNetwork.write(value.`networks`, buf)
            FfiConverterSequenceTypeFeature.write(value.`features`, buf)
            FfiConverterTypeLimits.write(value.`limits`, buf)
    }
}



/**
 * Resource limits of one runtime `Context` (ADR step 3). Every session of
 * the context counts toward them; two contexts never share them.
 *
 * The defaults suit a desktop host and parallel tests. A phone host sets
 * lower values, for example `Limits::default().with_max_sessions(8)`.
 */
data class Limits (
    /**
     * Live sessions (endpoints). Sessions that are still binding count too.
     */
    var `maxSessions`: kotlin.UInt
    , 
    /**
     * Gossip overlay paths over all sessions. One workspace uses at most 5.
     */
    var `maxOverlayPaths`: kotlin.UInt
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeLimits: FfiConverterRustBuffer<Limits> {
    override fun read(buf: ByteBuffer): Limits {
        return Limits(
            FfiConverterUInt.read(buf),
            FfiConverterUInt.read(buf),
        )
    }

    override fun allocationSize(value: Limits) = (
            FfiConverterUInt.allocationSize(value.`maxSessions`) +
            FfiConverterUInt.allocationSize(value.`maxOverlayPaths`)
    )

    override fun write(value: Limits, buf: ByteBuffer) {
            FfiConverterUInt.write(value.`maxSessions`, buf)
            FfiConverterUInt.write(value.`maxOverlayPaths`, buf)
    }
}





/**
 * The error of every public operation.
 *
 * Make it where the failure happens. Do not guess it from message text.
 *
 * # Pairing rule
 *
 * Variants that carry a `code` accept only codes from their own group:
 *
 * | Variant         | Codes                                              |
 * | --------------- | -------------------------------------------------- |
 * | `Storage`       | 300-399 (`StorageFailed`, `StorageCorrupt`, `CandidateStale`, `FormatNotSupported`) |
 * | `Transport`     | 400-499                                            |
 * | `Authorization` | 500-599                                            |
 * | `State`         | `WrongState`, `Unsupported`, 600-699               |
 *
 * The fields of an enum variant are public in Rust, so the compiler cannot
 * stop a wrong pair. Make errors with the checked constructors
 * ([`ApiError::new`] and the named ones such as [`ApiError::timeout`]); they
 * always pick the right variant. [`ApiError::is_well_formed`] checks a value,
 * and deserialization rejects a wrong pair.
 *
 * # No secrets
 *
 * `detail`, `reason`, `resource` and `kind` are for people. They must never
 * hold key material, invitation tokens, snapshots, plaintext payloads or
 * other secret bytes. Put only fixed text, lengths, counts and public IDs in
 * them.
 */
sealed class ApiException: kotlin.Exception() {
    
    class Closed(
        ) : ApiException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : ApiException() {
        override val message
            get() = ""
    }
    
    class DeadlineExceeded(
        ) : ApiException() {
        override val message
            get() = ""
    }
    
    class InvalidInput(
        
        val `field`: kotlin.String, 
        
        val `reason`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "field=${ `field` }, reason=${ `reason` }"
    }
    
    /**
     * Not in the ADR sketch; added so `ErrorCode::InvalidId` has a variant.
     */
    class InvalidId(
        
        val `kind`: kotlin.String, 
        
        val `reason`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "kind=${ `kind` }, reason=${ `reason` }"
    }
    
    /**
     * A resource is full for now (a queue, a worker pool). A later retry can
     * succeed. `limit` is 0 when the bound is not one fixed number.
     */
    class CapacityExceeded(
        
        val `resource`: kotlin.String, 
        
        val `limit`: kotlin.ULong, 
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "resource=${ `resource` }, limit=${ `limit` }, detail=${ `detail` }"
    }
    
    /**
     * A fixed limit is reached (sessions, advertisements, overlay paths).
     * It stays reached until something is released. `limit` is 0 when the
     * bound is not one fixed number. Added in API version 2.
     */
    class LimitReached(
        
        val `resource`: kotlin.String, 
        
        val `limit`: kotlin.ULong, 
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "resource=${ `resource` }, limit=${ `limit` }, detail=${ `detail` }"
    }
    
    class Storage(
        
        val `code`: ErrorCode, 
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    
    class Transport(
        
        val `code`: ErrorCode, 
        
        val `peer`: EndpointId?, 
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "code=${ `code` }, peer=${ `peer` }, detail=${ `detail` }"
    }
    
    class Authorization(
        
        val `code`: ErrorCode, 
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    
    class State(
        
        val `code`: ErrorCode, 
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    
    class Internal(
        
        val `detail`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): ApiException = FfiConverterTypeApiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeApiError : FfiConverterRustBuffer<ApiException> {
    override fun read(buf: ByteBuffer): ApiException {
        

        return when(buf.getInt()) {
            1 -> ApiException.Closed()
            2 -> ApiException.Cancelled()
            3 -> ApiException.DeadlineExceeded()
            4 -> ApiException.InvalidInput(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> ApiException.InvalidId(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> ApiException.CapacityExceeded(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> ApiException.LimitReached(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> ApiException.Storage(
                FfiConverterTypeErrorCode.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> ApiException.Transport(
                FfiConverterTypeErrorCode.read(buf),
                FfiConverterOptionalTypeEndpointId.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> ApiException.Authorization(
                FfiConverterTypeErrorCode.read(buf),
                FfiConverterString.read(buf),
                )
            11 -> ApiException.State(
                FfiConverterTypeErrorCode.read(buf),
                FfiConverterString.read(buf),
                )
            12 -> ApiException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ApiException): ULong {
        return when(value) {
            is ApiException.Closed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ApiException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ApiException.DeadlineExceeded -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ApiException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is ApiException.InvalidId -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is ApiException.CapacityExceeded -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`resource`)
                + FfiConverterULong.allocationSize(value.`limit`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ApiException.LimitReached -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`resource`)
                + FfiConverterULong.allocationSize(value.`limit`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ApiException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeErrorCode.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ApiException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeErrorCode.allocationSize(value.`code`)
                + FfiConverterOptionalTypeEndpointId.allocationSize(value.`peer`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ApiException.Authorization -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeErrorCode.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ApiException.State -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeErrorCode.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is ApiException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: ApiException, buf: ByteBuffer) {
        when(value) {
            is ApiException.Closed -> {
                buf.putInt(1)
                Unit
            }
            is ApiException.Cancelled -> {
                buf.putInt(2)
                Unit
            }
            is ApiException.DeadlineExceeded -> {
                buf.putInt(3)
                Unit
            }
            is ApiException.InvalidInput -> {
                buf.putInt(4)
                FfiConverterString.write(value.`field`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is ApiException.InvalidId -> {
                buf.putInt(5)
                FfiConverterString.write(value.`kind`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is ApiException.CapacityExceeded -> {
                buf.putInt(6)
                FfiConverterString.write(value.`resource`, buf)
                FfiConverterULong.write(value.`limit`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ApiException.LimitReached -> {
                buf.putInt(7)
                FfiConverterString.write(value.`resource`, buf)
                FfiConverterULong.write(value.`limit`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ApiException.Storage -> {
                buf.putInt(8)
                FfiConverterTypeErrorCode.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ApiException.Transport -> {
                buf.putInt(9)
                FfiConverterTypeErrorCode.write(value.`code`, buf)
                FfiConverterOptionalTypeEndpointId.write(value.`peer`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ApiException.Authorization -> {
                buf.putInt(10)
                FfiConverterTypeErrorCode.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ApiException.State -> {
                buf.putInt(11)
                FfiConverterTypeErrorCode.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is ApiException.Internal -> {
                buf.putInt(12)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * A stable numeric error code.
 *
 * Ranges:
 *
 * | Range   | Meaning                          |
 * | ------- | -------------------------------- |
 * | 1-99    | Lifecycle (closed, cancelled)    |
 * | 100-199 | Input and state                  |
 * | 200-299 | Capacity and limits              |
 * | 300-399 | Storage and candidates           |
 * | 400-499 | Transport and peers              |
 * | 500-599 | Authorization and membership     |
 * | 600-699 | Group consistency                |
 * | 900-999 | Internal                         |
 *
 * Rules: a number is never changed and never reused. New codes are added only
 * at the end of a range. A new code increments [`crate::API_VERSION`]. The
 * golden test in `tests/error_codes.rs` pins every value.
 *
 * On the wire (serde) a code is its number.
 */

enum class ErrorCode(val value: kotlin.UInt) {
    
    CLOSED(1u),
    CANCELLED(2u),
    DEADLINE_EXCEEDED(3u),
    INVALID_INPUT(100u),
    INVALID_ID(101u),
    WRONG_STATE(102u),
    UNSUPPORTED(103u),
    /**
     * A resource is full for now (a queue, a worker pool); retry later.
     */
    CAPACITY_EXCEEDED(200u),
    /**
     * A fixed limit is reached (sessions, advertisements, overlay paths).
     */
    LIMIT_REACHED(201u),
    STORAGE_FAILED(300u),
    STORAGE_CORRUPT(301u),
    /**
     * A staged candidate no longer matches the state it was staged from
     * (ADR decision 5). It stays in the storage range on purpose: a
     * candidate is a staged storage record, and "stale" means its stored
     * basis moved. Numbers never move, so this is also the stable place.
     */
    CANDIDATE_STALE(302u),
    /**
     * Stored data has a format this build does not read: newer than it
     * supports, or older than the first supported format (no legacy readers).
     */
    FORMAT_NOT_SUPPORTED(303u),
    PEER_UNREACHABLE(400u),
    TIMEOUT(401u),
    TRANSPORT_FAILED(402u),
    NOT_AUTHORIZED(500u),
    INVITATION_INVALID(501u),
    INVITATION_EXPIRED(502u),
    NOT_MEMBER(503u),
    EPOCH_MISMATCH(600u),
    POLICY_MISMATCH(601u),
    INTERNAL(900u);

    
    /**
     * Stable numeric code; independent of a language enum's ordinal.
     */ fun `number`(): kotlin.UInt {
            return FfiConverterUInt.lift(
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_arachne_api_fn_method_errorcode_number(FfiConverterTypeErrorCode.lower(this),
        _status)
}
    )
    }
    

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeErrorCode: FfiConverterRustBuffer<ErrorCode> {
    override fun read(buf: ByteBuffer) = try {
        ErrorCode.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ErrorCode) = 4UL

    override fun write(value: ErrorCode, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * One event from `Client::next_event` (ADR step 4). An event names the
 * queue or job that has work; the host then calls that queue's poll or
 * stage call. It carries no payload, so no data is copied twice.
 *
 * Queue events (`Control`, `MembershipChanged`, `ProtectedReceived`,
 * `PublicationReceived`) repeat until the host drains the queue. Job
 * events (`RecoveryReady`, `CurrentViewReady`, `InterestChanged`,
 * `Presence`) come once per ready job.
 */

enum class Event {
    
    /**
     * Reserved; admission requests arrive as `Control`.
     */
    ADMISSION_REQUEST,
    /**
     * Membership steps from gossip: `poll_membership_update`.
     */
    MEMBERSHIP_CHANGED,
    /**
     * A protected delivery: `poll_protected`.
     */
    PROTECTED_RECEIVED,
    /**
     * A recovery range ended: `poll_recovery_range`.
     */
    RECOVERY_READY,
    /**
     * A current-view repair ended: `poll_current_view`.
     */
    CURRENT_VIEW_READY,
    /**
     * An interest announcement ended: `poll_interest`.
     */
    INTEREST_CHANGED,
    /**
     * A presence answer came back: `poll_presence`.
     */
    PRESENCE,
    /**
     * Reserved; nearby invitations arrive as `Control`.
     */
    NEARBY_INVITATION,
    /**
     * The runtime ended the session (for example a removal). Call `close`.
     */
    CLOSED,
    /**
     * Peer control requests wait (admission, profile, presence, nearby):
     * `poll_admission` / `poll_control` until it has nothing.
     */
    CONTROL,
    /**
     * An unprotected fixture publication (no workspace): `poll`.
     */
    PUBLICATION_RECEIVED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeEvent: FfiConverterRustBuffer<Event> {
    override fun read(buf: ByteBuffer) = try {
        Event.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Event) = 4UL

    override fun write(value: Event, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





