 */
public object FfiConverterOptionalTypeEndpointId: FfiConverterRustBuffer<EndpointId?> {
    override fun read(buf: ByteBuffer): EndpointId? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterTypeEndpointId.read(buf)
    }

    override fun allocationSize(value: EndpointId?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterTypeEndpointId.allocationSize(value)
        }
    }

    override fun write(value: EndpointId?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterTypeEndpointId.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceTypeFeature: FfiConverterRustBuffer<List<Feature>> {
    override fun read(buf: ByteBuffer): List<Feature> {
        val len = buf.getInt()
        return List<Feature>(len) {
            FfiConverterTypeFeature.read(buf)
        }
    }

    override fun allocationSize(value: List<Feature>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeFeature.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<Feature>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeFeature.write(it, buf)
        }
    }
}




